def bind_source():
 p=read(C/'protocol.json')
 if p['freeze']['status']!='draft':raise ValueError('Cannot edit frozen protocol')
 sources,inputs=bindings();commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip()
 for path,want in sources.items():
  b=subprocess.check_output(['git','show',commit+':'+path],cwd=R)
  if hashlib.sha256(b).hexdigest()!=want:raise ValueError('Uncommitted source '+path)
 p['extensions'].update(source_sha256=sources,input_sha256=inputs)
 p['analysis_plan']['script']['sha256']=sha(C/'export_results.py')
 for a in p['arms']:a['instrument']['commit']=commit
 put(C/'protocol.json',p)
 s=yaml.safe_load((C/'specification.yaml').read_text());s['experiment']['input_bindings']={'source':[{'path':k,'sha256':v} for k,v in sources.items()],'fixtures':[{'path':k,'sha256':v} for k,v in inputs.items()],'external_runtime':external_bindings()};put(C/'specification.yaml',s)
 print('Staged source-bound draft; root copies config/protocol/specification/H to canonical destinations, validates/freezes and publishes.')

def bind_frozen():
 p=read(R/EX/'protocol.json')
 if p['freeze']['status']!='frozen':raise ValueError('Canonical protocol not frozen')
 s=yaml.safe_load((C/'specification.yaml').read_text())
 if s['experiment']['status']!='review_required':raise ValueError('Only draft spec may be bound')
 s['experiment']['execution_plan']['protocol_hashes']={EX+'/protocol.json':p['freeze']['protocol_sha256']}
 put(C/'protocol.json',p);put(C/'specification.yaml',s)
 print('Staged frozen protocol and bound review_required specification; root copies spec, commits/pushes before preview.')

